function renderImageControl(key,mapping,state,version){const box=controlShell(key,mapping),workflow=current,label=document.createElement('label'),copy=document.createElement('span'),line=document.createElement('br'),hint=document.createElement('small'),input=document.createElement('input'),status=document.createElement('div');label.className='upload-box';label.tabIndex=0;label.setAttribute('role','button');label.setAttribute('aria-label','选择或拖入'+String(mapping.label||'图片'));copy.textContent='点击上传或拖入 '+String(mapping.label||'图片');hint.textContent='PNG / JPEG / WebP，最大30MB';input.type='file';input.accept='image/png,image/jpeg,image/webp';copy.append(line,hint);label.append(copy,input);status.className='upload-status';status.setAttribute('aria-live','polite');status.textContent=state.mediaNames[key]?(state.mediaNames[key]+' 已上传'):'尚未上传';if(state.media[key]){label.classList.add('has-file');status.classList.add('ok')}const isActive=()=>version===renderVersion&&current?.id===workflow.id&&label.isConnected;const acceptFile=async file=>{if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){if(isActive()){status.textContent='只支持PNG、JPEG或WebP';status.className='upload-status err'}return}if(file.size>30*1024*1024){if(isActive()){status.textContent='图片超过30MB';status.className='upload-status err'}return}const uploadId=(state.uploadIds[key]||0)+1;state.uploadIds[key]=uploadId;if(isActive()){status.textContent='上传中…';status.className='upload-status';generateBtn.disabled=true}try{const data=await blobToB64(file),path=workflow.kind==='ai_app'?'/api/realcomic-upload':'/api/workflow-upload',payload={workflow:workflow.id,input_key:key,filename:file.name,data},result=await api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(state.uploadIds[key]!==uploadId)return;state.media[key]=result.uploadToken;state.mediaNames[key]=file.name;if(isActive()){label.classList.add('has-file');status.textContent='✓ '+file.name+' 已上传';status.className='upload-status ok'}}catch(error){if(state.uploadIds[key]!==uploadId)return;delete state.media[key];delete state.mediaNames[key];if(isActive()){label.classList.remove('has-file');status.textContent='上传失败：'+error.message;status.className='upload-status err'}}finally{if(current?.id===workflow.id)updateGenerateAvailability()}};label.onclick=event=>{if(event.target!==input)input.click()};label.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();input.click()}};label.ondragover=event=>{event.preventDefault();label.classList.add('is-dragging')};label.ondragleave=()=>label.classList.remove('is-dragging');label.ondrop=event=>{event.preventDefault();label.classList.remove('is-dragging');acceptFile(event.dataTransfer?.files?.[0])};input.onchange=()=>acceptFile(input.files[0]);box.append(label,status);controlRefs.set(key,{type:'image',mapping,control:input});return box}
