function showWorkflowLoadError(error){const box=document.createElement('div'),retry=document.createElement('button');box.className='config-state error';box.textContent='工作流配置加载失败：'+error.message;retry.className='retry';retry.type='button';retry.textContent='重新加载';retry.onclick=loadWorkflows;box.appendChild(document.createElement('br'));box.appendChild(retry);commonControls.replaceChildren(box);const empty=document.createElement('div');empty.className='config-state';empty.textContent='没有提交任何任务';advancedControls.replaceChildren(empty)}
async function loadWorkflows(){workflowSelect.disabled=true;workflowSelect.innerHTML='<option>正在加载…</option>';generateBtn.disabled=true;try{const all=await api('/api/workflows');workflows=all.filter(item=>item.backend==='runninghub'||['rh_workflow','ai_app'].includes(item.kind)).filter(item=>['rh_workflow','ai_app'].includes(item.kind));if(!workflows.length)throw new Error('配置中没有可用的真人化方案');workflowSelect.innerHTML='';workflows.forEach(workflow=>{const option=document.createElement('option');option.value=workflow.id;option.textContent=workflow.name;workflowSelect.appendChild(option)});workflowSelect.disabled=false;const requested=new URLSearchParams(location.search).get('workflow');selectWorkflow(workflows.some(x=>x.id===requested)?requested:workflows[0].id)}catch(error){current=null;workflowSelect.innerHTML='<option>加载失败</option>';showWorkflowLoadError(error);generateStatus.textContent='请检查服务后重试';updateGenerateAvailability()}}
