function snapshotSelections(){const state=ensureState(current);controlRefs.forEach((ref,key)=>{if(ref.type!=='image')state.params[key]=readControlValue(ref)});return{source_page:SOURCE_PAGE,workflow:current.id,params:JSON.parse(JSON.stringify(state.params)),media:JSON.parse(JSON.stringify(state.media)),media_names:JSON.parse(JSON.stringify(state.mediaNames))}}
function applySnapshot(snapshot){if(!snapshot||![SOURCE_PAGE,'realcomic'].includes(snapshot.source_page))return;const workflow=workflows.find(item=>item.id===(snapshot.workflow||'realcomic'));if(!workflow)return;const params=snapshot.source_page==='realcomic'?{requirements:snapshot.requirements||''}:JSON.parse(JSON.stringify(snapshot.params||{}));stateByWorkflow.set(workflow.id,{params,media:{},mediaNames:JSON.parse(JSON.stringify(snapshot.media_names||{}))});selectWorkflow(workflow.id);commonDrawer.classList.add('open');advancedDrawer.classList.add('open');generateStatus.textContent='参数已恢复；云端素材已过期，请重新上传';favOverlay.classList.remove('open')}
function statusText(job){const phase=job.provider_status||job.status;if(job.status==='done')return'✓ 已完成';if(job.status==='error')return'✗ '+(job.error||'失败');if(phase==='SUBMITTING')return'正在提交';if(phase==='QUEUED')return'排队中';if(phase==='RUNNING')return'运行中';if(phase==='FINALIZING')return'正在整理结果';return phase||'处理中'}
function coinText(job){if(job.rh_coins!==null&&job.rh_coins!==undefined&&job.rh_coins!=='')return'RH币：'+String(job.rh_coins);return(job.status==='done'||job.status==='error')?'RH币：未返回':'RH币：统计中'}
function createTaskCard(jobId,name){const card=document.createElement('article'),head=document.createElement('div'),spin=document.createElement('div'),info=document.createElement('div'),title=document.createElement('div'),meta=document.createElement('div'),timeEl=document.createElement('div'),view=document.createElement('button');card.className='task-card';card.dataset.jobId=jobId;head.className='task-head';spin.className='task-spin';title.className='task-name';title.textContent=String(name);meta.className='task-meta';meta.textContent='任务号：'+jobId+' · 等待状态';timeEl.className='task-time';timeEl.textContent='00:00';view.className='task-view';view.textContent='查看结果';view.hidden=true;info.append(title,meta);head.append(spin,info,timeEl,view);card.append(head);return{card,spin,meta,time:timeEl,view}}
function addTaskCard(jobId,name='真人化工作流'){if(tasks.has(jobId))return tasks.get(jobId);previewEmpty.classList.add('hidden');const parts=createTaskCard(jobId,name);taskList.prepend(parts.card);const task={...parts,started:Date.now(),timer:null};task.timer=setInterval(()=>task.time.textContent=fmtTime((Date.now()-task.started)/1000),500);tasks.set(jobId,task);taskCount.textContent=tasks.size+'个任务';return task}
function safeRemoteUrl(value){const raw=String(value??'');if(/[\x00-\x20\x7f"'<>`]/.test(raw))return'';try{const url=new URL(raw,location.origin);return ['http:','https:'].includes(url.protocol)&&!url.username&&!url.password?url.href:''}catch{return''}}
function isPreviewableImage(image,url){const kind=String(image.file_type||image.fileType||image.outputType||image.output_type||image.type||'').toLowerCase();if(kind.startsWith('image/')||['png','jpg','jpeg','webp','gif','avif'].includes(kind))return true;try{return /\.(png|jpe?g|webp|gif|avif)$/i.test(new URL(url).pathname)}catch{return false}}
function createResultItem(job,image,index){const item=document.createElement('div');item.className='job';const preview=safeRemoteUrl(image.preview_url||image.url),original=safeRemoteUrl(image.url),canPreview=isPreviewableImage(image,preview||original);const actions=document.createElement('div');actions.className='result-actions';const download=document.createElement('a');download.className='dl';download.target='_blank';download.rel='noopener';download.textContent=canPreview?'⬇ 下载原图':'⬇ 下载结果文件';if(original)download.href=original;else{download.removeAttribute('href');download.textContent='结果链接无效'};if(canPreview){const picture=document.createElement('img');picture.loading='lazy';picture.decoding='async';picture.alt='真人化结果';image.src=preview||original;picture.src=image.src;const favorite=document.createElement('button');favorite.className='dl favorite';favorite.textContent='♥ 收藏结果与全部参数';favorite.onclick=async event=>{event.target.disabled=true;try{await api('/api/favorites',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:job.id,image_index:index})});event.target.textContent='✓ 已收藏'}catch(error){event.target.disabled=false;event.target.textContent='收藏失败：'+error.message}};actions.append(favorite,download);item.append(picture,actions)}else{const file=document.createElement('div');file.className='file-result';file.textContent='结果文件 · 请下载查看';actions.append(download);item.append(file,actions)}return item}
const realismGalleryItems=[];let realismGalleryIndex=-1;
function renderRealismGallery(){if(realismGalleryIndex<0||!realismGalleryItems.length)return;const entry=realismGalleryItems[realismGalleryIndex],job=entry.job,image=entry.image,index=entry.index,preview=safeRemoteUrl(image.preview_url||image.url),original=safeRemoteUrl(image.url),canPreview=isPreviewableImage(image,preview||original);galleryMain.replaceChildren();galleryThumbs.replaceChildren();const meta=document.createElement('div');meta.className='gallery-meta note';meta.textContent=(image.stage_label||('结果 '+(realismGalleryIndex+1)))+' · '+String(job.wf_name||job.workflow||'真人化');galleryMain.appendChild(meta);if(canPreview){const picture=document.createElement('img');picture.src=preview||original;picture.alt='真人化结果';galleryMain.appendChild(picture)}else{const file=document.createElement('div');file.className='file-result';file.textContent='结果文件 · 请下载查看';galleryMain.appendChild(file)}const actions=document.createElement('div'),download=document.createElement('a'),favorite=document.createElement('button');actions.className='gallery-actions';download.className='dl';download.target='_blank';download.rel='noopener';download.href=original;download.textContent=canPreview?'⬇ 下载原图':'⬇ 下载结果文件';favorite.className='dl';favorite.textContent='♥ 收藏结果与全部参数';favorite.disabled=!canPreview;favorite.onclick=async()=>{favorite.disabled=true;try{await api('/api/favorites',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:job.id,image_index:index})});favorite.textContent='✓ 已收藏'}catch(error){favorite.disabled=false;favorite.textContent='收藏失败：'+error.message}};actions.append(favorite,download);galleryMain.appendChild(actions);realismGalleryItems.forEach((item,i)=>{const button=document.createElement('button');button.type='button';button.className='gallery-thumb'+(i===realismGalleryIndex?' active':'');button.onclick=()=>{realismGalleryIndex=i;renderRealismGallery()};if(isPreviewableImage(item.image,item.image.preview_url||item.image.url)){const thumb=document.createElement('img');thumb.src=safeRemoteUrl(item.image.preview_url||item.image.url);button.appendChild(thumb)}else button.textContent='ZIP';galleryThumbs.appendChild(button)});galleryPrev.disabled=galleryNext.disabled=realismGalleryItems.length<2;mediaGallery.hidden=false;previewEmpty.classList.add('hidden')}
function renderResults(job){(job.images||[]).forEach((image,index)=>{const key=job.id+':'+index;if(!realismGalleryItems.some(item=>item.key===key))realismGalleryItems.push({key,job,image,index})});if(realismGalleryItems.length){realismGalleryIndex=realismGalleryItems.length-1;renderRealismGallery()}}
async function pollTask(jobId,name){const task=addTaskCard(jobId,name);let failures=0;while(tasks.has(jobId)){try{const job=await api('/api/job/'+jobId);failures=0;task.meta.textContent='任务号：'+jobId+' · '+statusText(job)+' · '+coinText(job);if(job.status==='done'||job.status==='error'){if(task.timer)clearInterval(task.timer);task.timer=null;task.time.textContent=fmtTime(job.elapsed||0);task.spin.className='task-spin '+(job.status==='done'?'done':'err');forgetActiveJob(jobId);if(job.status==='done'){renderResults(job);task.view.hidden=false;task.view.onclick=()=>renderResults(job)};return job}}catch(error){failures++;task.meta.textContent='任务号：'+jobId+' · 状态连接中断，重试 '+failures+'/6';if(failures>=6){if(task.timer)clearInterval(task.timer);task.spin.className='task-spin err';task.meta.textContent='任务号：'+jobId+' · 暂时无法获取状态，刷新可恢复';return}}await new Promise(resolve=>setTimeout(resolve,failures?3000:1800))}}
async function submitWorkflow(){if(!current||generateBtn.disabled)return;const snapshot=snapshotSelections(),state=ensureState(current);generateBtn.disabled=true;generateBtn.setAttribute('aria-busy','true');generateStatus.textContent='正在提交…';let pending={};try{pending=JSON.parse(localStorage.getItem(pendingSubmitKey)||'{}')}catch{}let client_request_id=pending.workflow===current.id&&pending.id?pending.id:'realism-'+Date.now()+'-'+Math.random().toString(36).slice(2);localStorage.setItem(pendingSubmitKey,JSON.stringify({workflow:current.id,id:client_request_id}));const body={workflow:current.id,media:state.media,params:state.params,client_request_id,selection_snapshot:snapshot};const submitPath=current.kind==='ai_app'?'/api/ai-app-generate':'/api/workflow-generate';try{const response=await api(submitPath,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});localStorage.removeItem(pendingSubmitKey);rememberActiveJob(response.job_id);addTaskCard(response.job_id,current.name);generateStatus.textContent=(response.deduplicated?'已恢复':'已提交')+'，任务号：'+response.job_id;pollTask(response.job_id,current.name)}catch(error){const definitiveRejection=error.status>=400&&error.status<500;if(definitiveRejection)localStorage.removeItem(pendingSubmitKey);const running=error.data?.running_job||error.data?.running_jobs?.join('、');generateStatus.textContent='提交失败：'+error.message+(running?'；正在运行任务号：'+running:'')+(definitiveRejection?'':'；再次点击将使用同一请求号恢复')}finally{generateBtn.setAttribute('aria-busy','false');updateGenerateAvailability()}}
async function restoreTasks(){await Promise.all(getActiveIds().map(async id=>{try{const job=await api('/api/job/'+id);const name=job.wf_name||job.workflow||'真人化工作流';addTaskCard(id,name);if(job.status==='done'||job.status==='error'){forgetActiveJob(id);const task=tasks.get(id);if(task.timer)clearInterval(task.timer);task.timer=null;task.time.textContent=fmtTime(job.elapsed||0);task.spin.className='task-spin '+(job.status==='done'?'done':'err');task.meta.textContent='任务号：'+id+' · '+statusText(job)+' · '+coinText(job);if(job.status==='done'){renderResults(job);task.view.hidden=false;task.view.onclick=()=>renderResults(job)}}else pollTask(id,name)}catch{forgetActiveJob(id)}}))}
function createHistoryItem(job){const card=document.createElement('div'),title=document.createElement('b'),note=document.createElement('div'),button=document.createElement('button');card.className='job';title.textContent=String(job.wf_name||job.workflow||'真人化工作流');note.className='note';note.textContent=statusText(job)+' · '+coinText(job)+' · 任务号：'+String(job.id||'未知')+' · '+String(job.elapsed??'—')+'秒';button.className='dl';button.textContent='查看结果';button.onclick=()=>{renderResults(job);histOverlay.classList.remove('open')};card.append(title,note,button);return card}
async function history(){histList.textContent='加载中…';try{const ids=new Set(workflows.map(item=>item.id)),items=(await api('/api/jobs?scope=realism')).filter(job=>ids.has(job.workflow)||job.style_id==='realism');histList.replaceChildren();if(!items.length){const empty=document.createElement('div');empty.className='job note';empty.textContent='暂无真人化历史';histList.appendChild(empty)}else items.forEach(job=>histList.appendChild(createHistoryItem(job)))}catch(error){const failed=document.createElement('div');failed.className='job';failed.textContent='历史加载失败：'+error.message;histList.replaceChildren(failed)}}
function createFavoriteItem(item){const card=document.createElement('div'),note=document.createElement('div'),image=document.createElement('img'),apply=document.createElement('button'),download=document.createElement('a');card.className='job';note.className='note';note.textContent=String(item.selection_snapshot?.workflow||'真人化工作流');image.loading='lazy';image.decoding='async';image.alt='收藏的真人化结果';image.src=safeRemoteUrl(item.preview_url||item.image_url);apply.className='dl apply';apply.textContent='↺ 套用全部参数';apply.onclick=()=>applySnapshot(item.selection_snapshot);download.className='dl';download.target='_blank';download.rel='noopener';const original=safeRemoteUrl(item.image_url);download.textContent=original?'⬇ 下载收藏原图':'收藏链接无效';if(original)download.href=original;card.append(note,image,apply,download);return card}
async function favorites(){favList.textContent='加载中…';try{const items=(await api('/api/favorites')).filter(item=>[SOURCE_PAGE,'realcomic'].includes(item.selection_snapshot?.source_page));favList.replaceChildren();if(!items.length){const empty=document.createElement('div');empty.className='job note';empty.textContent='暂无真人化收藏';favList.appendChild(empty)}else items.forEach(item=>favList.appendChild(createFavoriteItem(item)))}catch(error){const failed=document.createElement('div');failed.className='job';failed.textContent='收藏加载失败：'+error.message;favList.replaceChildren(failed)}}
function ensureActiveNavVisible(){const nav=document.querySelector('.topnav'),active=nav?.querySelector('.active');if(!nav||!active)return;const left=active.offsetLeft-Math.max(0,(nav.clientWidth-active.offsetWidth)/2);nav.scrollLeft=Math.max(0,left)}
const CREATOR_ROUTES=['/','/realism','/video'];function scheduleRoutePrefetch(){}
document.querySelectorAll('.config-drawer-head').forEach(button=>button.onclick=()=>button.closest('.config-drawer').classList.toggle('open'));workflowSelect.onchange=()=>selectWorkflow(workflowSelect.value);generateBtn.onclick=submitWorkflow;galleryPrev.onclick=()=>{if(realismGalleryItems.length){realismGalleryIndex=(realismGalleryIndex-1+realismGalleryItems.length)%realismGalleryItems.length;renderRealismGallery()}};galleryNext.onclick=()=>{if(realismGalleryItems.length){realismGalleryIndex=(realismGalleryIndex+1)%realismGalleryItems.length;renderRealismGallery()}};addEventListener('resize',ensureActiveNavVisible);ensureActiveNavVisible();histOpen.onclick=()=>{histOverlay.querySelector('.library-scroll').scrollTop=0;histOverlay.classList.add('open');history()};favOpen.onclick=()=>{favOverlay.querySelector('.library-scroll').scrollTop=0;favOverlay.classList.add('open');favorites()};document.querySelectorAll('.library-overlay .close').forEach(button=>button.onclick=()=>button.closest('.library-overlay').classList.remove('open'));document.querySelectorAll('.library-overlay').forEach(overlay=>overlay.onclick=event=>{if(event.target===overlay)overlay.classList.remove('open')});scheduleRoutePrefetch();(window.requestIdleCallback||function(fn){setTimeout(fn,200)})(preloadWorkflowPreviews);loadWorkflows().then(restoreTasks);

return {styleBoot:null};
